void MainWindow::unc_page(){auto children=body_.Children();children.Append(label(tr(L"UNC access",L"UNC 访问"),24));try{settings_=Settings::load();}catch(...){report(std::current_exception());}auto root=box(tr(L"Source directory",L"源目录"),text(settings_.root.u16string()));auto alias=box(tr(L"Share name",L"共享名称"),text(settings_.alias));auto idle=box(tr(L"Idle timeout (seconds)",L"空闲超时（秒）"),text(std::to_string(settings_.idle_seconds)));auto max=box(tr(L"Maximum idle images",L"最大空闲镜像数"),text(std::to_string(settings_.max_idle_images)));auto memory=box(tr(L"Cache per image (MiB)",L"每个镜像的缓存（MiB）"),text(std::to_string(settings_.cache_mib)));auto drives=check(tr(L"Expose local and mapped drives",L"公开本地和映射的驱动器"),settings_.include_drives);auto login=check(tr(L"Start at login",L"登录时启动"),settings_.start_at_login);auto language=combo(tr(L"Language (restart application)",L"语言（重启应用后生效）"),{L"system",L"en-US",L"zh-CN"},settings_.language=="zh-CN"?2:settings_.language=="en-US"?1:0);children.Append(root);children.Append(button(tr(L"Browse",L"浏览"),[this,root]{try{auto p=pick(true);if(!p.empty())root.Text(text(p.front().u16string()));}catch(...){report(std::current_exception());}}));for(auto e:std::vector<UIElement>{alias,idle,max,memory,drives,login,language})children.Append(e);auto state=label(agent_running()?tr(L"Running",L"运行中"):tr(L"Stopped",L"已停止"));children.Append(state);auto row=panel(true);row.Children().Append(button(tr(L"Apply",L"应用"),[=,this]{try{auto s=settings_;s.root=fs::path(u16(root.Text()));s.alias=u16(alias.Text());s.idle_seconds=number(idle,86400);s.max_idle_images=number(max,1024);s.cache_mib=number(memory,4096);s.include_drives=checked(drives);s.start_at_login=checked(login);s.language=selected_text(language);run([this,s,state](std::stop_token t){bool running=agent_running();s.save();if(running){stop_agent(t);start_agent(t);}return [this,s,state]{settings_=s;state.Text(agent_running()?tr(L"Running",L"运行中"):tr(L"Stopped",L"已停止"));};},tr(L"Applying settings",L"正在应用设置"));}catch(...){report(std::current_exception());}}));row.Children().Append(button(tr(L"Start",L"启动"),[this,state]{run([this,state](std::stop_token t){start_agent(t);return [this,state]{state.Text(tr(L"Running",L"运行中"));};},tr(L"Starting UNC agent",L"正在启动后台进程"));}));row.Children().Append(button(tr(L"Stop",L"停止"),[this,state]{run([this,state](std::stop_token t){stop_agent(t);return [this,state]{state.Text(tr(L"Stopped",L"已停止"));};},tr(L"Stopping UNC agent",L"正在停止后台进程"));}));children.Append(row);children.Append(label(L"\\\\sfs$\\path\\image.squashfs\n\\\\sfs$\\UNC\\server\\share\\image.dwarfs\n\\\\sfs.localhost\\C\\image.erofs"));}
void MainWindow::about_page(){body_.Children().Append(label(L"WinArchiveFSPro",28));body_.Children().Append(label(tr(L"Read-only archive filesystem manager\nSquashFS · DwarFS · EROFS\nC++23 · WinUI 3 · WinFsp",L"只读存档文件系统管理器\nSquashFS · DwarFS · EROFS\nC++23 · WinUI 3 · WinFsp")));body_.Children().Append(button(tr(L"Check WinFsp runtime",L"检查 WinFsp 运行时"),[this]{try{status_.Text(text(winfsp_runtime_info()));}catch(...){report(std::current_exception());}}));body_.Children().Append(button(tr(L"Open tools folder",L"打开工具目录"),[this]{try{open_in_explorer((application_directory()/L"tools").u16string());}catch(...){report(std::current_exception());}}));}
void MainWindow::apply_command_line(){try{int count=0;auto raw=CommandLineToArgvW(GetCommandLineW(),&count);if(!raw)return;struct Guard{LPWSTR* p;~Guard(){LocalFree(p);}}guard{raw};std::vector<fs::path> args;for(int i=1;i<count;++i)args.emplace_back(raw[i]);if(args.empty())return;if(args[0]==L"--pack-list"&&args.size()==2){auto list=fs::absolute(args[1]);if(fs::file_size(list)>16u<<20)throw std::runtime_error("selection list too large");std::ifstream in(list,std::ios::binary);if(!in)throw std::runtime_error("cannot read selection list");std::vector<char> bytes((std::istreambuf_iterator<char>(in)),{});if(bytes.size()%2||bytes.size()>16u<<20)throw std::runtime_error("invalid selection list");std::u16string name;for(size_t i=0;i<bytes.size();i+=2){auto ch=static_cast<char16_t>(static_cast<unsigned char>(bytes[i])|(static_cast<unsigned>(static_cast<unsigned char>(bytes[i+1]))<<8));if(ch)name+=ch;else if(!name.empty()){sources_.emplace_back(name);name.clear();}}if(!name.empty())throw std::runtime_error("invalid selection list");in.close();if(fs::equivalent(list.parent_path(),fs::temp_directory_path())&&list.filename().wstring().starts_with(L"wsq")){std::error_code ec;fs::remove(list,ec);}navigate(1);}else if(args[0]==L"--pack"&&args.size()>1){sources_.assign(args.begin()+1,args.end());navigate(1);}else if(args[0]==L"--unc"&&args.size()==2){auto p=args[1];run([this,p](std::stop_token s){open_unc(p,s);return [this]{Close();};},tr(L"Opening UNC path",L"正在打开 UNC 路径"));}else if(args[0]==L"--eject"&&args.size()==2){auto d=args[1].u16string();run([this,d](std::stop_token){eject_volume(d);return [this]{Close();};},tr(L"Ejecting",L"正在弹出"));}else if(args.size()==1)open_image(args[0]);else if(args.size()==2&&(args[0]==L"--open"||args[0]==L"--mount"||args[0]==L"--extract"))open_image(args[1],args[0]==L"--mount"?1:args[0]==L"--extract"?2:0);else throw std::invalid_argument("invalid command line");}catch(...){report(std::current_exception());}}
